mapper.select:
SELECT t.id, t.transfer_no AS transferNo, t.from_factory_id AS fromFactoryId, ff.name AS fromFactoryName, t.from_warehouse_id AS fromWarehouseId, fw.name AS fromWarehouseName, t.to_factory_id AS toFactoryId, tf.name AS toFactoryName, t.to_warehouse_id AS toWarehouseId, tw.name AS toWarehouseName, t.status, t.audit_time AS auditTime, t.remark, t.create_time AS createTime, COALESCE(agg.line_count, 0) AS lineCount, COALESCE(agg.total_qty, 0) AS totalQty, COALESCE(agg.total_amount, 0) AS totalAmount FROM org_transfer t LEFT JOIN org_factory ff ON ff.id = t.from_factory_id AND ff.deleted = 0 LEFT JOIN org_factory tf ON tf.id = t.to_factory_id AND tf.deleted = 0 LEFT JOIN base_warehouse fw ON fw.id = t.from_warehouse_id AND fw.deleted = 0 LEFT JOIN base_warehouse tw ON tw.id = t.to_warehouse_id AND tw.deleted = 0 LEFT JOIN agg ON agg.transfer_id = t.id WHERE t.deleted = 0
AND t.status = #{q.status}
AND t.from_factory_id = #{q.fromFactoryId}
AND t.to_factory_id = #{q.toFactoryId}
AND (t.transfer_no LIKE CONCAT('%', #{q.keyword}, '%') OR ff.name LIKE CONCAT('%', #{q.keyword}, '%') OR tf.name LIKE CONCAT('%', #{q.keyword}, '%'))
AND t.create_time >= CONCAT(#{q.beginDate}, ' 00:00:00')
AND t.create_time <= CONCAT(#{q.endDate}, ' 23:59:59')
ORDER BY t.id DESC
